/* ---------------- Metin yardımcıları ---------------- */
const up = (v) => String(v ?? '').replace(/\u0130/g, 'I').replace(/\u0131/g, 'i')
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '').toUpperCase();
